2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.Locale;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.util.Sha256;
11	
12	/**
13	 * Identifies the owners that make up a household — those sharing a last name (compared
14	 * case-insensitively with collapsed whitespace) and a normalized address (see
15	 * {@link AddressNormalizer}). Used both to derive an owner's identity key
16	 * ({@link EnsureUniqueIdentity}) and to group knowing house-mates under a shared, stable
17	 * household id ({@link AssignHousehold}).
18	 */
19	final class Households {
20	
21	    private Households() {
22	    }
23	
24	    /**
25	     * The household id a create request would resolve to: the shared id for its last name
26	     * and address when it opts in with {@code sharesHousehold=true} and existing owners are
27	     * already at that household, otherwise null. Mirrors what {@link AssignHousehold} would
28	     * assign, so the identity check compares the candidate against the same id.
29	     */
30	    static String resolveHouseholdId(OwnerRepository repository, OwnerFieldsDto request) {
31	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
32	            return null;
33	        }
34	        if (membersAt(repository, request.getLastName(), request.getAddress()).isEmpty()) {
35	            return null;
36	        }
37	        return householdId(request.getLastName(), request.getAddress());
38	    }
39	
40	    /** Existing owners whose last name and address match the given household. */
41	    static List<Owner> membersAt(OwnerRepository repository, String lastName, String address) {
42	        String key = key(lastName, address);
43	        List<Owner> members = new ArrayList<>();
44	        for (Owner owner : repository.findAll()) {
45	            if (key.equals(key(owner.getLastName(), owner.getAddress()))) {
46	                members.add(owner);
47	            }
48	        }
49	        return members;
50	    }
51	
52	    /** How many existing owners already carry the given household id (0 when it is null). */
53	    static int memberCount(OwnerRepository repository, String householdId) {
54	        if (householdId == null) {
55	            return 0;
56	        }
57	        int count = 0;
58	        for (Owner owner : repository.findAll()) {
59	            if (householdId.equals(owner.getHouseholdId())) {
60	                count++;
61	            }
62	        }
63	        return count;
64	    }
65	
66	    /**
67	     * A stable identifier for the household with the given last name and address. Derived
68	     * from the normalized key, so every member of the same household resolves to the same
69	     * value regardless of when they are created.
70	     */
71	    static String householdId(String lastName, String address) {
72	        return "HH-" + Sha256.hex(key(lastName, address)).substring(0, 24).toUpperCase(Locale.ROOT);
73	    }
74	
75	    /** The normalized last name and address joined into a single household key. */
76	    private static String key(String lastName, String address) {
77	        return normalizeName(lastName) + '\n' + AddressNormalizer.normalize(address);
78	    }
79	
80	    /** Case-fold and collapse whitespace so trivial spacing/casing differences still match. */
81	    private static String normalizeName(String value) {
82	        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
83	    }
84	}
