3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * Business-day calendar rules for owner registration. A registration date must fall on a
8	 * business day; a Saturday or Sunday rolls forward to the following Monday. Used when
9	 * resolving the effective registration date ({@link ResolveRegistrationDate}) so that the
10	 * stored date, everything derived from it (e.g. the membership number's year segment) and
11	 * the per-day create limit all agree on the adjusted business day.
12	 */
13	final class BusinessDays {
14	
15	    private BusinessDays() {
16	    }
17	
18	    /** The given date, or the next Monday when it falls on a Saturday or Sunday. */
19	    static LocalDate rollForward(LocalDate date) {
20	        DayOfWeek day = date.getDayOfWeek();
21	        if (day == DayOfWeek.SATURDAY) {
22	            return date.plusDays(2);
23	        }
24	        if (day == DayOfWeek.SUNDAY) {
25	            return date.plusDays(1);
26	        }
27	        return date;
28	    }
29	}
