7	/**
8	 * The bulk-signup warning policy: whether today's owner registrations have grown unusually
9	 * high. It shares the same per-day accumulation as the create limit ({@link EnsureDailyLimit}),
10	 * counting owners by registration date on the current business day, and is surfaced as the
11	 * read-only {@code bulkSignupWarning} flag on every owner response.
12	 */
13	final class BulkSignup {
14	
15	    /** Registering more than this many owners on a single business day raises the warning. */
16	    static final long BULK_SIGNUP_THRESHOLD = 80;
17	
18	    private BulkSignup() {
19	    }
20	
21	    /**
22	     * Whether more than {@link #BULK_SIGNUP_THRESHOLD} owners have already been registered for
23	     * the current business day (weekends rolled forward, matching {@link ResolveRegistrationDate}).
24	     */
25	    static boolean warningRaised(OwnerRepository ownerRepository) {
26	        LocalDate today = BusinessDays.rollForward(LocalDate.now());
27	        return DailyRegistrations.countOn(ownerRepository, today) > BULK_SIGNUP_THRESHOLD;
28	    }
29	}
