5	/**
6	 * The single derived identity of an owner used for duplicate detection: the normalized
7	 * telephone, the (optional) email and the household id joined by {@code '|'}. Two owners
8	 * are duplicates exactly when their whole identity keys are equal, so the previously
9	 * separate telephone, email and household checks are all expressed through this one value.
10	 *
11	 * <p>Both the create pipeline (which compares a candidate's key against every existing
12	 * owner) and the response mapper (which returns the key) derive it here, so they agree on
13	 * what an owner's identity is. The telephone and email are already canonical by the time a
14	 * key is built — the create steps normalize them before the check, and stored owners hold
15	 * the normalized values — so this class only joins them.
16	 */
17	public final class IdentityKey {
18	
19	    private IdentityKey() {
20	    }
21	
22	    /** The identity key for the given owner, from its stored telephone, email and household id. */
23	    public static String of(Owner owner) {
24	        return of(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
25	    }
26	
27	    /**
28	     * The identity key for the given parts: {@code telephone + '|' + (email or empty) + '|'
29	     * + (householdId or empty)}. A null or blank email or household id contributes an empty
30	     * segment, so an owner without one still has a well-formed key.
31	     */
32	    public static String of(String telephone, String email, String householdId) {
33	        return orEmpty(telephone) + '|' + orEmpty(email) + '|' + orEmpty(householdId);
34	    }
35	
36	    private static String orEmpty(String value) {
37	        return (value == null || value.isBlank()) ? "" : value;
38	    }
39	}
