5	/**
6	 * Derives an owner's numeric membership level, assigned on creation. The level starts at
7	 * 1, gains 1 when the owner has an email address, gains 1 when the owner has no namesakes
8	 * ({@code namesakeCount == 0}), and is capped at {@link #MAX} (level 4 is reserved for
9	 * tenure).
10	 */
11	public final class MembershipLevel {
12	
13	    /** Level assigned to every owner before any bonuses. */
14	    public static final int BASE = 1;
15	
16	    /** Highest level assignable on creation; level 4 is reserved for tenure. */
17	    public static final int MAX = 3;
18	
19	    private MembershipLevel() {
20	    }
21	
22	    /** The membership level for the given owner, from {@link #BASE} to {@link #MAX}. */
23	    public static int of(Owner owner) {
24	        int level = BASE;
25	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
26	            level++;
27	        }
28	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
29	            level++;
30	        }
31	        return Math.min(level, MAX);
32	    }
33	}
